package io.tenvyr.control.runtime;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.tenvyr.platform.Db;
import io.tenvyr.platform.Json;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/** External Git changes happen between committed intent and atomic terminal persistence. */
public final class WorkspaceExecutionService {
    public static final String PROCESS_INSTANCE_ID=UUID.randomUUID().toString();
    static final Set<String> ACTIVE=ConcurrentHashMap.newKeySet();
    public record ReleaseClaim(String operationId,String ownerProcessId,String ownerToken) {}
    public enum Registration { REGISTERED,ABSENT,UNKNOWN }
    @FunctionalInterface public interface GitRunner {ProcessBoundary.Result run(String cwd,List<String> args);}
    private final Db db;private final Path root;private final GitRunner git;private volatile boolean terminalShouldFail;
    public WorkspaceExecutionService(Db db){this(db,Path.of(System.getenv().getOrDefault("TENVYR_WORKSPACE_ROOT",Path.of(System.getProperty("java.io.tmpdir"),"tenvyr-workspaces").toString())),(cwd,args)->ProcessBoundary.run("git",args,Path.of(cwd),WorkspaceService.gitEnvironment(),120000,16384));}
    public WorkspaceExecutionService(Db db,Path root,GitRunner git){this.db=db;this.root=root.toAbsolutePath().normalize();this.git=git;}
    public Registration worktreeIsRegistered(String source,String execution){try{String target=Files.exists(Path.of(execution))?Path.of(execution).toRealPath().toString():Path.of(execution).toAbsolutePath().normalize().toString();ProcessBoundary.Result result=git.run(source,List.of("worktree","list","--porcelain"));if(!ok(result)||result.stdout().isBlank())return Registration.UNKNOWN;for(String block:result.stdout().replace("\r\n","\n").trim().split("\n\n+")){String[] lines=block.split("\n");if(!lines[0].startsWith("worktree ")||lines[0].length()<=9||Arrays.stream(lines).noneMatch(l->l.startsWith("HEAD ")&&l.length()>5))return Registration.UNKNOWN;if(lines[0].substring(9).equals(target))return Registration.REGISTERED;}return Registration.ABSENT;}catch(Exception e){return Registration.UNKNOWN;}}
    public ObjectNode allocateExecutionWorkspace(JsonNode workspace,String mode,String allocationKey){if(!Set.of("shared","git-worktree").contains(mode))throw fail("ALLOCATION_CONFLICT","Unknown workspace mode");if(allocationKey!=null&&allocationKey.length()>255)throw fail("ALLOCATION_CONFLICT","Allocation key too long");ObjectNode existing=allocationKey==null?null:db.one("SELECT * FROM workspace_executions WHERE \"allocationKey\"=?",allocationKey);if(existing!=null)return existingAllocation(existing,workspace,mode);
        String source=WorkspaceService.resolveWorkspacePath(Json.text(workspace,"path"));String sha=Json.text(workspace,"headSha",null),repo=Json.text(workspace,"repoRoot",null);if(mode.equals("git-worktree")&&(repo==null||sha==null||!sha.matches("[0-9a-fA-F]{40}")))throw fail("NOT_A_GIT_REPOSITORY","Git isolation requires a detectable repository with HEAD");String id=UUID.randomUUID().toString(),shortId=id.substring(0,12);Path execution=root.resolve("run-"+shortId);if(mode.equals("git-worktree")){try{Files.createDirectories(root);Path canonical=root.toRealPath();if(!canonical.equals(root)||Files.isSymbolicLink(root))throw fail("EXECUTION_ROOT_UNWRITABLE","Execution root must be canonical and not a symlink");String allowed=System.getenv("EXECUTOR_HOST_ALLOWED_ROOT");if(allowed!=null&&!canonical.startsWith(Path.of(allowed).toRealPath()))throw fail("EXECUTION_ROOT_UNWRITABLE","Execution root is outside allowed executor root");}catch(java.io.IOException e){throw fail("EXECUTION_ROOT_UNWRITABLE","Execution root is not writable");}}
        ObjectNode row;try{row=db.insert("workspace_executions",Json.object("id",id,"sourceWorkspaceId",workspace.get("workspaceId"),"sourcePath",source,"mode",mode,"executionPath",mode.equals("shared")?source:execution.toString(),"baseBranch",workspace.get("branch"),"baseHeadSha",workspace.get("headSha"),"ownerRunId",null,"allocationKey",allocationKey,"state",mode.equals("shared")?"READY":"ALLOCATING"));}catch(Db.Failure e){if(allocationKey!=null&&"23505".equals(e.sqlState())){ObjectNode concurrent=db.one("SELECT * FROM workspace_executions WHERE \"allocationKey\"=?",allocationKey);if(concurrent!=null)return existingAllocation(concurrent,workspace,mode);}throw e;}
        if(mode.equals("shared"))return row;ProcessBoundary.Result add=git.run(repo,List.of("worktree","add","-b","tenvyr/run-"+shortId,execution.toString(),sha));if(!ok(add)&&worktreeIsRegistered(repo,execution.toString())!=Registration.REGISTERED){transition(id,"FAILED",Json.object("failureCode","WORKTREE_CREATE_FAILED"));throw fail("WORKTREE_CREATE_FAILED","Git worktree creation failed");}try{Path real=execution.toRealPath();if(!Files.isDirectory(real)||!real.startsWith(root)||!real.equals(execution)||!headMatches(real.toString(),sha))throw fail("ALLOCATION_MISMATCH","Worktree identity mismatch");return transition(id,"READY",Json.object("executionPath",real.toString()));}catch(Exception e){transition(id,"FAILED",Json.object("failureCode",e instanceof RuntimeFailure f?f.code():"WORKTREE_MISSING"));throw e instanceof RuntimeFailure f?f:fail("WORKTREE_MISSING","Worktree creation did not produce an execution directory");}}
    private ObjectNode existingAllocation(ObjectNode row,JsonNode workspace,String mode){if(!Json.text(row,"sourceWorkspaceId").equals(Json.text(workspace,"workspaceId"))||!Json.text(row,"mode").equals(mode)||(row.hasNonNull("baseHeadSha")&&workspace.hasNonNull("headSha")&&!row.get("baseHeadSha").equals(workspace.get("headSha")))||(mode.equals("shared")&&!Json.text(row,"sourcePath").equals(Json.text(workspace,"path"))))throw fail("ALLOCATION_CONFLICT","Allocation key has conflicting parameters");if(Set.of("READY","IN_USE").contains(Json.text(row,"state")))return row;if(Json.text(row,"state").equals("ALLOCATING")&&worktreeIsRegistered(Json.text(row,"sourcePath"),Json.text(row,"executionPath"))==Registration.REGISTERED&&headMatches(Json.text(row,"executionPath"),Json.text(row,"baseHeadSha",null)))return transition(Json.text(row,"id"),"READY",Json.object());throw fail(Json.text(row,"failureCode","ALLOCATION_IN_PROGRESS"),"Existing allocation is not ready");}
    private boolean headMatches(String cwd,String sha){ProcessBoundary.Result head=git.run(cwd,List.of("rev-parse","HEAD"));return ok(head)&&(sha==null||head.stdout().trim().equals(sha));}
    public ObjectNode bindExecutionWorkspace(Db tx,String id,String run){int count=tx.execute("UPDATE workspace_executions SET \"ownerRunId\"=?,state='IN_USE',\"updatedAt\"=now() WHERE id=? AND \"ownerRunId\" IS NULL AND state='READY'",run,id);if(count!=1)throw fail("LEASE_NOT_AVAILABLE","Execution workspace is not available");return row(tx,id,false);}
    public ObjectNode allocateSharedExecutionWorkspace(Db tx,JsonNode workspace,String run){ObjectNode lease=tx.insert("workspace_executions",Json.object("sourceWorkspaceId",workspace.get("workspaceId"),"sourcePath",workspace.get("path"),"mode","shared","executionPath",workspace.get("path"),"baseBranch",workspace.get("branch"),"baseHeadSha",workspace.get("headSha"),"state","READY"));return bindExecutionWorkspace(tx,Json.text(lease,"id"),run);}
    public ObjectNode transferExecutionWorkspace(Db tx,String leaseId,String sourceRun,String destinationRun){ObjectNode source=row(tx,leaseId,true);if(!Json.text(source,"ownerRunId").equals(sourceRun)||!Json.text(source,"state").equals("PRESERVED")||!Json.text(source,"mode").equals("git-worktree")||!source.hasNonNull("executionPath"))throw fail("LEASE_NOT_AVAILABLE","Preserved worktree is not transferable");if(tx.execute("UPDATE workspace_executions SET state='TRANSFERRED',\"updatedAt\"=now() WHERE id=? AND \"ownerRunId\"=? AND state='PRESERVED'",leaseId,sourceRun)!=1)throw fail("LEASE_NOT_AVAILABLE","Lease transfer raced");return tx.insert("workspace_executions",Json.object("sourceWorkspaceId",source.get("sourceWorkspaceId"),"sourcePath",source.get("sourcePath"),"mode","git-worktree","executionPath",source.get("executionPath"),"baseBranch",source.get("baseBranch"),"baseHeadSha",source.get("baseHeadSha"),"ownerRunId",destinationRun,"state","IN_USE"));}
    public JsonNode executionWorkspaceIdentityForRun(String run){return executionWorkspaceIdentityForRun(db,run);}
    public JsonNode executionWorkspaceIdentityForRun(Db tx,String run){ObjectNode r=tx.one("SELECT * FROM workspace_executions WHERE \"ownerRunId\"=?",run);return r==null?null:identity(r);}
    public JsonNode identityForExecution(String execution){ObjectNode run=db.one("SELECT id FROM coordination_runs WHERE \"executionId\"=?",execution);return run==null?null:executionWorkspaceIdentityForRun(Json.text(run,"id"));}
    public static JsonNode identity(JsonNode row){if(!Set.of("READY","IN_USE").contains(Json.text(row,"state"))||!row.hasNonNull("executionPath"))return null;return Json.object("schemaVersion",1,"workspaceExecutionId",row.get("id"),"sourceWorkspaceId",row.get("sourceWorkspaceId"),"mode",row.get("mode"),"path",row.get("executionPath"),"baseBranch",row.get("baseBranch"),"baseHeadSha",row.get("baseHeadSha"));}
    public ObjectNode preserveExecutionWorkspaceForRun(Db tx,String run){ObjectNode row=tx.one("SELECT * FROM workspace_executions WHERE \"ownerRunId\"=? AND state='IN_USE' FOR UPDATE",run);if(row==null)return null;Boolean dirty=null;if(Json.text(row,"mode").equals("git-worktree")&&row.hasNonNull("executionPath")){ProcessBoundary.Result status=git.run(Json.text(row,"executionPath"),List.of("status","--porcelain"));if(ok(status))dirty=!status.stdout().trim().isEmpty();}return tx.update("workspace_executions",Json.text(row,"id"),Json.object("state","PRESERVED","hasUncommittedWork",dirty,"updatedAt",Instant.now().toString()));}
    public int reconcileWorkspaceExecutions(){int transitions=0;for(ObjectNode lease:db.query("SELECT * FROM workspace_executions WHERE state IN ('ALLOCATING','READY','IN_USE','RELEASE_REQUESTED')")){String id=Json.text(lease,"id"),state=Json.text(lease,"state");if(state.equals("ALLOCATING")){if(lease.hasNonNull("executionPath")&&worktreeIsRegistered(Json.text(lease,"sourcePath"),Json.text(lease,"executionPath"))==Registration.REGISTERED&&headMatches(Json.text(lease,"executionPath"),Json.text(lease,"baseHeadSha",null))){transition(id,"READY",Json.object());transitions++;}else if(old(lease,60000)){transition(id,"FAILED",Json.object("failureCode","ALLOCATION_INTERRUPTED"));transitions++;}}else if(state.equals("READY")&&!lease.hasNonNull("ownerRunId")&&old(lease,60000)){transition(id,"FAILED",Json.object("failureCode","RUN_NOT_BOUND"));transitions++;}else if(state.equals("IN_USE")){ObjectNode run=db.one("SELECT phase FROM coordination_runs WHERE id=?",lease.get("ownerRunId"));if(run!=null&&Set.of("ACCEPTED","FAILED","CANCELLED","LIMIT_REACHED").contains(Json.text(run,"phase"))){db.transaction(tx->preserveExecutionWorkspaceForRun(tx,Json.text(lease,"ownerRunId")));transitions++;}}else if(state.equals("RELEASE_REQUESTED")){ObjectNode action=lease.hasNonNull("releaseOperationId")?db.one("SELECT * FROM operator_actions WHERE id=?",lease.get("releaseOperationId")):null;if(!correlated(action,lease)){db.transaction(tx->{ObjectNode current=row(tx,id,true);if(Json.text(current,"state").equals("RELEASE_REQUESTED")){tx.update("workspace_executions",id,Json.object("state","PRESERVED","failureCode","RELEASE_UNAUTHORIZED","releaseOperationId",null));tx.execute("DELETE FROM workspace_release_locks WHERE \"workspaceExecutionId\"=?",id);}return null;});transitions++;}else if(lease.hasNonNull("executionPath")&&worktreeIsRegistered(Json.text(lease,"sourcePath"),Json.text(lease,"executionPath"))==Registration.ABSENT){db.transaction(tx->{ObjectNode current=row(tx,id,true),a=tx.one("SELECT * FROM operator_actions WHERE id=? FOR UPDATE",action.get("id"));if(correlated(a,current)){tx.update("workspace_executions",id,Json.object("state","REMOVED","releaseOperationId",null));tx.execute("DELETE FROM workspace_release_locks WHERE \"workspaceExecutionId\"=? AND \"releaseOperationId\"=?",id,a.get("id"));tx.update("operator_actions",Json.text(a,"id"),Json.object("outcome",Json.object("workspaceExecutionId",id,"state","REMOVED")));}return null;});transitions++;}}}transitions+=db.execute("DELETE FROM workspace_release_locks l WHERE NOT EXISTS (SELECT 1 FROM operator_actions a WHERE a.id::text=l.\"releaseOperationId\" AND a.outcome->>'pending'='true') AND NOT EXISTS (SELECT 1 FROM workspace_executions w WHERE w.id=l.\"workspaceExecutionId\" AND (w.state NOT IN ('PRESERVED','FAILED') OR w.\"releaseOperationId\" IS NOT NULL))");return transitions;}
    public ObjectNode releaseExecutionWorkspace(String id,ReleaseClaim claim){ObjectNode lease=db.transaction(tx->{assertClaim(tx,id,claim);ObjectNode r=row(tx,id,true);if(Json.text(r,"mode").equals("shared"))throw fail("SHARED_MODE_NO_REMOVAL","Shared workspace has no isolated worktree to remove");String state=Json.text(r,"state"),op=Json.text(r,"releaseOperationId",null);if(state.equals("RELEASE_REQUESTED")){if(!Objects.equals(op,claim.operationId()))throw fail("RELEASE_IN_PROGRESS","Another operation owns workspace release");return r;}if(!Set.of("PRESERVED","FAILED").contains(state))throw fail("LEASE_NOT_RELEASABLE","Release requires a preserved or failed lease");ObjectNode lock=tx.one("SELECT * FROM workspace_release_locks WHERE \"workspaceExecutionId\"=? FOR UPDATE",id);if(lock!=null&&!Json.text(lock,"releaseOperationId").equals(claim.operationId())){ObjectNode owner=tx.one("SELECT outcome FROM operator_actions WHERE id=?",lock.get("releaseOperationId"));if(owner!=null&&Json.bool(owner.path("outcome"),"pending",false))throw fail("RELEASE_IN_PROGRESS","Another operation owns release lock");tx.execute("DELETE FROM workspace_release_locks WHERE \"workspaceExecutionId\"=?",id);}tx.execute("INSERT INTO workspace_release_locks (\"workspaceExecutionId\",\"releaseOperationId\") VALUES (?,?) ON CONFLICT (\"workspaceExecutionId\") DO NOTHING",id,claim.operationId());return tx.update("workspace_executions",id,Json.object("state","RELEASE_REQUESTED","releaseOperationId",claim.operationId(),"failureCode",null,"hasUncommittedWork",null));});
        assertClaim(db,id,claim);if(!lease.hasNonNull("executionPath"))return refuse(id,claim,"LEASE_PATH_MISSING",false);String source=Json.text(lease,"sourcePath"),path=Json.text(lease,"executionPath");verifyOwnedPath(path);Registration registration=worktreeIsRegistered(source,path);if(registration==Registration.UNKNOWN)return refuse(id,claim,"WORKTREE_STATE_UNKNOWN",false);if(registration==Registration.ABSENT)return persistTerminalRelease(id,claim,"REMOVED",null,null);assertClaim(db,id,claim);ProcessBoundary.Result removed=git.run(source,List.of("worktree","remove",path));if(ok(removed)||worktreeIsRegistered(source,path)==Registration.ABSENT)return persistTerminalRelease(id,claim,"REMOVED",null,null);Registration after=worktreeIsRegistered(source,path);String error=removed.stderr().toLowerCase(Locale.ROOT);boolean dirty=error.contains("contains modified")||error.contains("contains untracked")||error.contains("untracked files")||error.contains("modified files")||error.contains("dirty");return refuse(id,claim,after==Registration.UNKNOWN?"WORKTREE_STATE_UNKNOWN":dirty?"WORKTREE_DIRTY":"WORKTREE_REMOVE_FAILED",dirty);}
    private ObjectNode refuse(String id,ReleaseClaim claim,String code,boolean dirty){persistTerminalRelease(id,claim,"PRESERVED",code,dirty?true:null);throw fail(code,"Workspace preserved: "+code);}
    private void verifyOwnedPath(String path){Path candidate=Path.of(path).toAbsolutePath().normalize();if(!candidate.startsWith(root)||candidate.equals(root)||!candidate.getFileName().toString().startsWith("run-"))throw fail("RELEASE_UNAUTHORIZED","Execution path outside Tenvyr owned root");try{if(Files.exists(candidate)&&(!candidate.toRealPath().equals(candidate)||Files.isSymbolicLink(candidate)))throw fail("RELEASE_UNAUTHORIZED","Execution path identity changed");}catch(java.io.IOException e){throw fail("WORKTREE_STATE_UNKNOWN","Execution path cannot be resolved");}}
    public ObjectNode persistTerminalRelease(String id,ReleaseClaim claim,String state,String code,Boolean dirty){return db.transaction(tx->{assertClaim(tx,id,claim);ObjectNode lease=row(tx,id,true);if(!Objects.equals(Json.text(lease,"releaseOperationId",null),claim.operationId()))throw fail("RELEASE_UNAUTHORIZED","Release owner changed");ObjectNode lock=tx.one("SELECT * FROM workspace_release_locks WHERE \"workspaceExecutionId\"=? FOR UPDATE",id);if(lock!=null&&!Json.text(lock,"releaseOperationId").equals(claim.operationId()))throw fail("RELEASE_IN_PROGRESS","Release lock owner changed");ObjectNode terminal=Json.object("workspaceExecutionId",id,"state",state);if(code!=null){terminal.put("failureCode",code);terminal.put("error","Workspace preserved: "+code);terminal.put("refusal",true);}if(dirty!=null)terminal.put("hasUncommittedWork",dirty);ObjectNode result=tx.update("workspace_executions",id,Json.object("state",state,"failureCode",code,"hasUncommittedWork",dirty,"releaseOperationId",null,"updatedAt",Instant.now().toString()));if(terminalShouldFail){terminalShouldFail=false;throw new IllegalStateException("injected terminal failure");}tx.execute("DELETE FROM workspace_release_locks WHERE \"workspaceExecutionId\"=? AND \"releaseOperationId\"=?",id,claim.operationId());tx.update("operator_actions",claim.operationId(),Json.object("outcome",terminal));return result;});}
    public void setTerminalShouldFail(boolean fail){terminalShouldFail=fail;}
    private void assertClaim(Db tx,String id,ReleaseClaim claim){if(claim==null||!PROCESS_INSTANCE_ID.equals(claim.ownerProcessId())||claim.ownerToken()==null)throw fail("RELEASE_UNAUTHORIZED","Exact release claim required");ObjectNode action=tx.one("SELECT * FROM operator_actions WHERE id=?",claim.operationId());JsonNode outcome=action==null?Json.object():action.path("outcome");if(action==null||!Json.text(action,"action").equals("release-execution-workspace")||!Json.text(action,"targetId").equals(id)||!Json.bool(outcome,"pending",false)||!Json.text(outcome,"phase").equals("EXECUTING")||!Json.text(outcome,"ownerToken").equals(claim.ownerToken())||!Json.text(outcome,"ownerProcessId").equals(claim.ownerProcessId()))throw fail("RELEASE_UNAUTHORIZED","Exact pending executing release claim required");}
    private static boolean correlated(JsonNode action,JsonNode lease){return action!=null&&Json.text(action,"action").equals("release-execution-workspace")&&Json.text(action,"targetId").equals(Json.text(lease,"id"))&&Json.bool(action.path("outcome"),"pending",false)&&Set.of("REQUESTED","EXECUTING").contains(Json.text(action.path("outcome"),"phase"));}
    private ObjectNode transition(String id,String state,ObjectNode fields){fields.put("state",state);fields.put("updatedAt",Instant.now().toString());return db.update("workspace_executions",id,fields);}
    private static boolean old(JsonNode row,long millis){return Instant.now().toEpochMilli()-Instant.parse(Json.text(row,"createdAt")).toEpochMilli()>millis;}
    private static boolean ok(ProcessBoundary.Result r){return r!=null&&Objects.equals(r.status(),0)&&!r.timedOut()&&!r.exceeded();}
    static ObjectNode row(Db db,String id,boolean lock){ObjectNode row=db.one("SELECT * FROM workspace_executions WHERE id=?"+(lock?" FOR UPDATE":""),id);if(row==null)throw fail("LEASE_NOT_FOUND","Execution workspace missing");return row;}
    static RuntimeFailure fail(String code,String message){return new RuntimeFailure(code,message);}
}
